value:alertRowSrc:
"function _alertRow(r, names) {
  const rid = r.router_id || null;
  return {
    id: r.id,
    routerId: rid,
    alertType: r.alert_type,
    // Derived, never stored: see alerter.labelFor. Keeping the key in the
    // database and the name in code means renaming an alert is not a migration.
    label: alerter.labelFor(r.alert_type),
    // Without this an alert cannot say which router it belongs to, which is the
    // whole difficulty with three identical update alerts.
    routerName: (names && rid && names.get(rid)) || null,
    subject: r.subject || null,
    detail: r.detail || null,
    firedAt: r.fired_at,
    resolvedAt: r.resolved_at || null,
    acknowledgedAt: r.acknowledged_at || null,
    acknowledgedBy: r.acknowledged_by || null,
  };
}"

value:labelForSrc:
"function labelFor(alertType) {
  if (!alertType) return 'Alert';
  const key = String(alertType).toLowerCase();
  if (ALERT_LABELS[key]) return ALERT_LABELS[key];
  // Anything unmapped still reads as words rather than as a database column, so
  // a future alert type degrades gracefully instead of leaking its key.
  return key.split('_').filter(Boolean)
    .map(w => _LABEL_ACRONYMS[w] || (w.charAt(0).toUpperCase() + w.slice(1)))
    .join(' ');
}"

value:labelsSrc:
"const ALERT_LABELS = {
  routeros_update:  'Update Available',
  routeros_updated: 'Up To Date',
  connectivity:     'Router Connectivity',
}"
